def choose_move(observation):
    def gv(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def is_num(v):
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return int(v)

    def pick_first(*vals):
        for v in vals:
            if v is not None:
                return v
        return None

    def extract_pos(v):
        if isinstance(v, dict):
            x = pick_first(gv(v, "x"), gv(v, "col"), gv(v, "cx"), gv(v, 0))
            y = pick_first(gv(v, "y"), gv(v, "row"), gv(v, "cy"), gv(v, 1))
            if is_num(x) and is_num(y):
                return [int(x), int(y)]
        elif isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def entity_positions(obj):
        out = []
        if isinstance(obj, dict):
            for k in ("positions", "cells", "items", "entities", "agents", "resources", "enemies", "targets", "goals"):
                arr = gv(obj, k)
                if isinstance(arr, list):
                    for a in arr:
                        p = extract_pos(a)
                        if p is not None:
                            out.append(p)
        elif isinstance(obj, list):
            for a in obj:
                p = extract_pos(a)
                if p is not None:
                    out.append(p)
        return out

    def get_self_pos(obs):
        for k in ("position", "pos", "agent_pos", "player_pos", "self_pos", "location", "loc"):
            p = extract_pos(gv(obs, k))
            if p is not None:
                return p
        self_obj = gv(obs, "self")
        if self_obj is not None:
            for k in ("position", "pos", "agent_pos", "player_pos", "location", "loc"):
                p = extract_pos(gv(self_obj, k))
                if p is not None:
                    return p
            p = extract_pos(self_obj)
            if p is not None:
                return p
        return None

    def get_grid(obs):
        for k in ("grid", "board", "map", "terrain", "state"):
            g = gv(obs, k)
            if isinstance(g, list) and g:
                return g
        return None

    def get_size(obs, grid):
        w = pick_first(gv(obs, "width"), gv(obs, "w"))
        h = pick_first(gv(obs, "height"), gv(obs, "h"))
        if is_num(w) and is_num(h):
            return int(w), int(h)
        if isinstance(grid, list) and grid and isinstance(grid[0], list):
            return len(grid[0]), len(grid)
        return None, None

    obs = observation if isinstance(observation, dict) else {}
    me = get_self_pos(obs)
    grid = get_grid(obs)
    width, height = get_size(obs, grid)

    resources = []
    enemies = []
    targets = []
    for key in ("resources", "resource_positions", "food", "coins", "items"):
        resources.extend(entity_positions(gv(obs, key)))
    for key in ("enemies", "enemy_positions", "opponents", "opponent_positions", "adversaries", "hazards"):
        enemies.extend(entity_positions(gv(obs, key)))
    for key in ("targets", "goals", "objectives", "territory", "capture_points", "cells"):
        targets.extend(entity_positions(gv(obs, key)))

    # Scan grid for visible cues if entity lists are absent.
    if isinstance(grid, list) and grid and isinstance(grid[0], list):
        for y, row in enumerate(grid):
            if not isinstance(row, list):
                continue
            for x, cell in enumerate(row):
                if cell is None:
                    continue
                if isinstance(cell, str):
                    c = cell[:1]
                    if c in ("R", "$", "*", "F", "C", "G"):
                        resources.append([x, y])
                    elif c in ("E", "X", "e", "H", "M", "O"):
                        enemies.append([x, y])
                    elif c in (".", "?", "T"):
                        targets.append([x, y])
                elif is_num(cell):
                    if cell > 0:
                        targets.append([x, y])

    if me is None:
        return [0, 0]

    mx, my = me[0], me[1]

    def dist2(p):
        dx = p[0] - mx
        dy = p[1] - my
        return dx * dx + dy * dy

    def nearest(lst):
        best = None
        best_d = None
        for p in lst:
            if not (isinstance(p, (list, tuple)) and len(p) >= 2):
                continue
            d = dist2(p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

