        (-1, 0),  (0, 0),  (1, 0),
        (-1, 1),  (0, 1),  (1, 1),
    ]

    def passable(x, y):
        if width is not None and height is not None:
            if x < 0 or y < 0 or x >= width or y >= height:
                return False
        if isinstance(grid, list) and grid and isinstance(grid[0], list):
            if 0 <= y < len(grid) and 0 <= x < len(grid[y]):
                cell = grid[y][x]
                if isinstance(cell, str) and cell[:1] in ("#", "W", "X"):
                    return False
                if is_num(cell) and cell < 0:
                    return False
        return True

    center = None
    if width is not None and height is not None:
        center = [width // 2, height // 2]

    best_move = [0, 0]
    best_score = None

    for dx, dy in moves:
        nx, ny = mx + dx, my + dy
        if not passable(nx, ny):
            continue
        score = 0.0

        # Prefer collecting nearby resources.
        if res is not None:
            nd = (res[0] - nx) * (res[0] - nx) + (res[1] - ny) * (res[1] - ny)
            score += 30.0 / (1.0 + nd)
            if nd == 0:
                score += 50.0

        # Prefer general objectives / territory.
        if tgt is not None:
            nd = (tgt[0] - nx) * (tgt[0] - nx) + (tgt[1] - ny) * (tgt[1] - ny)
            score += 10.0 / (1.0 + nd)

        # Avoid enemies unless clearly pursuing.
        if ene is not None:
            nd = (ene[0] - nx) * (ene[0] - nx) + (ene[1] - ny) * (ene[1] - ny)
            score -= 40.0 / (1.0 + nd)
            if nd == 0:
                score -= 100.0

        # Flee if enemy is very close and no immediate resource gain.
        if ene is not None:
            curd = (ene[0] - mx) * (ene[0] - mx) + (ene[1] - my) * (ene[1] - my)
            newd = (ene[0] - nx) * (ene[0] - nx) + (ene[1] - ny) * (ene[1] - ny)
            if newd > curd:
                score += 2.0

        # Mild preference for movement over idling when exploring.
        if dx == 0 and dy == 0:
            score -= 0.2
        else:
            score += 0.1

        # Center bias when nothing else is known.
        if center is not None and res is None and ene is None and tgt is None:
            cd = (center[0] - nx) * (center[0] - nx) + (center[1] - ny) * (center[1] - ny)
            score += 1.0 / (1.0 + cd)

        # Small tie-breakers for determinism.
        score += dx * 0.001 + dy * 0.0001

        if best_score is None or score > best_score:
            best_score = score
            best_move = [dx, dy]

    return [clamp_step(best_move[0]), clamp_step(best_move[1])]

